#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; double l, w;
    while (cin >> n >> l >> w) {
        vector<pair<double,double>> iv;
        double halfw = w/2.0;
        for (int i=0;i<n;i++){
            double pos, r; cin >> pos >> r;
            if (r <= halfw) continue;
            double eff = sqrt(r*r - halfw*halfw);
            iv.push_back({pos-eff, pos+eff});
        }
        sort(iv.begin(), iv.end());
        double covered = 0;
        int count = 0, i = 0;
        bool ok = true;
        while (covered < l) {
            double best = covered;
            while (i < (int)iv.size() && iv[i].first <= covered + 1e-9) {
                best = max(best, iv[i].second);
                i++;
            }
            if (best <= covered + 1e-9) { ok = false; break; }
            covered = best;
            count++;
        }
        cout << (ok ? count : -1) << "\n";
    }
}

